fn eval_rpn(expr: &str) -> Result<i64, String> {
    let mut tokens = expr.split_whitespace();
    let mut stack: Vec<i64> = Vec::new();

    for token in tokens {
        let token = token.trim();
        if token == "" {
            continue;
        }
        match token {
            // operators
            "+" => {
                if stack.len() < 2 {
                    return Err(format!("missing operand for operator +"));
                }
                let b = stack.pop().expect("not enough operands for operator +");
                let a = stack.pop().expect("not enough operands for operator +");
                stack.push(a + b);
            }
            "-" => {
                if stack.len() < 2 {
                    return Err(format!("missing operand for operator -"));
                }
                let b = stack.pop().expect("not enough operands for operator -");
                let a = stack.pop().expect("not enough operands for operator -");
                stack.push(a - b);
            }
            "*" => {
                if stack.len() < 2 {
                    return Err(format!("missing operand for operator *"));
                }
                let b = stack.pop().expect("not enough operands for operator *");
                let a = stack.pop().expect("not enough operands for operator *");
                stack.push(a * b);
            }
            "/" => {
                if stack.len() < 2 {
                    return Err(format!("missing operand for operator /"));
                }
                let b = stack.pop().expect("not enough operands for operator /");
                let a = stack.pop().expect("not enough operands for operator /");
                if b == 0 {
                    return Err("division by zero".to_string());
                }
                stack.push(a / b);
            }
            _ => {
                // token is an operator but not one of the known ones
                return Err(format!("invalid token: {}", token));
            }
        }
    }

    // after processing all tokens, stack must contain exactly one element
    if stack.len() != 1 {
        let result = stack.pop().expect("extra operands left");
        return Err(format!("extra operands: {:?}", stack));
    }
    Ok(stack.pop().expect("no result"))
}
