fn mat_mul(a: &[Vec<f64>], b: &[Vec<f64>]) -> Option<Vec<Vec<f64>>> {
    // Check that each matrix has rows of equal length (i.e., all rows have same number of columns)
    let a_rows = a.len();
    let a_cols = match a.first()?.len() {
        n => n,
        _ => panic!("a is empty")
    };
    for row in &a[1..] {
        if row.len() != a_cols {
            return None;
        }
    }

    let b_rows = b.len();
    let b_cols = match b.first()?.len() {
        n => n,
        _ => panic!("b is empty")
    };
    for row in &b[1..] {
        if row.len() != b_cols {
            return None;
        }
    }

    // Compatibility: a_cols must equal b_rows for multiplication A * B
    if a_cols != b_rows {
        return None;
    }

    // Result dimensions: a_rows x b_cols
    let mut result = vec![vec![0.0; b_cols]; a_rows];

    for i in 0..a_rows {
        for j in 0..b_cols {
            let mut sum = 0.0;
            for k in 0..a_cols {
                sum += a[i][k] * b[k][j];
            }
            result[i][j] = sum;
        }
    }

    Some(result)
}
