pub struct Node {
    pub val: i32,
    pub next: Option<Box<Node>>,
}

/// Creates a linked list from the given vector of values.
/// Returns the head node (as a Box<Node>) wrapped in Some, or None if the vector is empty.
fn from_vec(v: &[i32]) -> Option<Box<Node>> {
    if v.is_empty() {
        return None;
    }
    let mut prev = None;
    for &val in v.iter().rev() {
        let node = Box::new(Node { val: val, next: Some(prev) });
        prev = Some(node);
    }
    Some(prev)
}

/// Converts a linked list (starting at head) to a vector of values.
/// Returns the values in order from head to tail.
fn to_vec(head: &Option<Box<Node>>) -> Vec<i32> {
    let mut values = Vec::new();
    let mut current = head;
    while let Some(node) = current {
        values.push(node.val);
        current = current.as_ref().and_then(|n| n.next);
    }
    values
