fn parallel_sum(data: &[u64], threads: usize) -> u64 {
    let data_len = data.len();
    let mut total = 0u64;
    let chunk_size = (data_len + threads - 1) / threads; // ceil division

    for _ in 0..threads {
        let start = chunk_size * _;
        let end = if _ < threads - 1 { start + chunk_size } else { data_len };
        let chunk: Vec<u64> = &data[start..end];
        let sum: u64 = chunk.iter().sum();
        total += sum;
    }
    total
}
