use std::collections::BinaryHeap;
use std::cmp::Reverse;

/// Computes the shortest path distance from `src` to `dst` in a directed graph
/// with non-negative edge weights.
///
/// Parameters:
/// - `n`: number of nodes (nodes are labeled 0..n-1)
/// - `edges`: slice of tuples (from_node, to_node, weight)
/// - `src`: source node index
/// - `dst`: destination node index
///
/// Returns `Some(distance)` if `dst` is reachable from `src`, otherwise `None`.
fn shortest_path(n: usize, edges: &[(usize, usize, u32)], src: usize, dst: usize) -> Option<u32> {
    // Build adjacency list: for each node, a vector of (neighbor, weight)
    let mut adj: Vec<Vec<(usize, u32)>> = vec![vec![]; n];
    for &(u, v, w) in edges {
        adj[u].push((v, w));
    }

    // Dijkstra's algorithm using a binary heap (max-heap by default)
    // We store (negative_distance, node) to simulate min-heap.
    let mut dist = vec![u32::MAX; n];
    let mut heap: BinaryHeap<Reverse<(u32, usize)>> = BinaryHeap::new();
    // Initialize source distance to 0
    dist[src] = 0;
    // Push (0, src) as Reverse((0, src)) because BinaryHeap is max-heap
    heap.push(Reverse((0, src)));

    while let Some(Reverse((mut current_dist, u))) = heap.pop() {
        // If we have already found a shorter distance to u, skip
        if current_dist > dist[u] {
            continue;
        }
        // If we reached the destination, we can break early (optional)
        if u == dst {
            break;
        }
        // Explore neighbors
        for &(v, w) in &adj[u] {
            let new_dist = current_dist + w;
            if new_dist < dist[v] {
                dist[v] = new_dist;
                heap.push(Reverse((new_dist, v)));
            }
        }
